// The JSON library survey's number vectors (decision v8-arch-json-fast-float),
// regenerated by vectors/gen_numbers.py into the directory given as the first
// argument and checked to be the survey's set (SHA-256) before this runs.
// Rules: docs/architecture/target/v2/json-module-declaration.zh-Hant.md 8.2.
#include <bit>
#include <charconv>
#include <cstdint>
#include <cstdio>
#include <fstream>
#include <string>
#include <string_view>
#include <vector>

#include "engine/json/Document.hpp"

using GYO::Engine::Json::JsonErrorCode;
using GYO::Engine::Json::Parse;

namespace {

std::vector<std::string> Lines(const std::string& path) {
    std::ifstream in(path, std::ios::binary);
    std::vector<std::string> lines;
    std::string line;
    while (std::getline(in, line)) {
        if (!line.empty() && line.back() == '\r') line.pop_back();
        lines.push_back(line);
    }
    return lines;
}

struct Tally {
    std::size_t checked = 0;
    std::size_t mismatched = 0;
    void Fail(const std::string_view file, const std::string& text, const std::string& reference, const std::string& got) {
        ++mismatched;
        if (mismatched <= 20) {
            std::printf("MISMATCH %.*s: %s reference %s got %s\n", static_cast<int>(file.size()), file.data(),
                        text.c_str(), reference.c_str(), got.c_str());
        }
    }
};

std::string Hex(const double value) {
    char buffer[32];
    std::snprintf(buffer, sizeof buffer, "d:%016llx",
                  static_cast<unsigned long long>(std::bit_cast<std::uint64_t>(value)));
    return buffer;
}

void CheckDoubles(const std::string& dir, const std::string& name, const std::size_t expectedCount, Tally& tally,
                  bool& countsOk) {
    const auto texts = Lines(dir + "/" + name + ".txt");
    const auto references = Lines(dir + "/" + name + "_ref.txt");
    if (texts.size() != expectedCount || references.size() != expectedCount) {
        std::printf("COUNT %s: %zu texts, %zu references, expected %zu\n", name.c_str(), texts.size(),
                    references.size(), expectedCount);
        countsOk = false;
        return;
    }
    for (std::size_t i = 0; i < texts.size(); ++i) {
        ++tally.checked;
        auto document = Parse(texts[i]);
        const std::string& reference = references[i];
        if (reference.starts_with("E:")) {
            if (document || document.error().code != JsonErrorCode::NumberOutOfRange) {
                tally.Fail(name, texts[i], reference, document ? "accepted" : ToString(document.error().code));
            }
            continue;
        }
        if (!document) {
            tally.Fail(name, texts[i], reference, ToString(document.error().code));
            continue;
        }
        auto value = document->Root().AsDouble();
        const std::string got = value ? Hex(*value) : ToString(value.error().code);
        if (got != reference) tally.Fail(name, texts[i], reference, got);
    }
}

void CheckIntegers(const std::string& dir, const std::size_t expectedCount, Tally& tally, bool& countsOk) {
    const auto texts = Lines(dir + "/num_int.txt");
    const auto references = Lines(dir + "/num_int_ref.txt");
    if (texts.size() != expectedCount || references.size() != expectedCount) {
        std::printf("COUNT num_int: %zu texts, %zu references, expected %zu\n", texts.size(), references.size(),
                    expectedCount);
        countsOk = false;
        return;
    }
    for (std::size_t i = 0; i < texts.size(); ++i) {
        ++tally.checked;
        auto document = Parse(texts[i]);
        if (!document) {
            tally.Fail("num_int", texts[i], references[i], ToString(document.error().code));
            continue;
        }
        const auto root = document->Root();
        const auto asInt = root.AsInt64();
        const auto asUint = root.AsUint64();
        const std::string i64 = asInt ? "i:" + std::to_string(*asInt) : ToString(asInt.error().code);
        const std::string u64 = asUint ? "u:" + std::to_string(*asUint) : ToString(asUint.error().code);
        const std::string& reference = references[i];
        std::string expectInt = "NumberOutOfRange";
        std::string expectUint = "NumberOutOfRange";
        if (reference.starts_with("i:")) {
            expectInt = reference;
            const bool negative = reference[2] == '-';
            if (!negative) expectUint = "u:" + reference.substr(2);
        } else if (reference.starts_with("u:")) {
            expectUint = reference;
        }
        if (i64 != expectInt || u64 != expectUint) {
            tally.Fail("num_int", texts[i], reference, i64 + " " + u64);
        }
    }
}

} // namespace

int main(const int argc, char** argv) {
    if (argc != 2) {
        std::printf("usage: gyo_json_vector_tests <vector directory>\n");
        return 2;
    }
    const std::string dir = argv[1];
    Tally tally;
    bool countsOk = true;
    CheckDoubles(dir, "num_fixed", 40, tally, countsOk);
    CheckDoubles(dir, "num_gen", 200000, tally, countsOk);
    CheckIntegers(dir, 10010, tally, countsOk);
    std::printf("checked %zu numbers (expected 210050), %zu mismatched\n", tally.checked, tally.mismatched);
    return countsOk && tally.checked == 210050 && tally.mismatched == 0 ? 0 : 1;
}
